package com.confluo.common.mapper;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Tests for {@link BaseMapper}. Only {@code toResponseList} has an implementation to exercise; the
 * other three methods are generated by MapStruct per resource.
 */
class BaseMapperTest {

    /** the entity stand-in */
    private record Entity(String name) {
    }

    /** the response stand-in */
    private record Response(String name) {
    }

    /**
     * A minimal implementation that records the entities it was asked to convert, so the default
     * method's use of {@code toResponse} can be observed.
     */
    private static final class TestMapper implements BaseMapper<Entity, Entity, Entity, Response> {

        private final List<Entity> converted = new ArrayList<>();

        @Override
        public Response toResponse(Entity entity) {
            converted.add(entity);
            return new Response(entity.name());
        }

        @Override
        public void createEntityFromRequest(Entity entity, Entity request) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void updateEntityFromRequest(Entity entity, Entity request) {
            throw new UnsupportedOperationException();
        }
    }

    private final TestMapper mapper = new TestMapper();

    @Test
    void toResponseListConvertsEveryEntityInOrder() {
        List<Response> responses = mapper.toResponseList(
                List.of(new Entity("first"), new Entity("second"), new Entity("third")));

        assertThat(responses).containsExactly(
                new Response("first"), new Response("second"), new Response("third"));
    }

    @Test
    void toResponseListDelegatesToToResponseOncePerEntity() {
        Entity first = new Entity("first");
        Entity second = new Entity("second");

        mapper.toResponseList(List.of(first, second));

        assertThat(mapper.converted).containsExactly(first, second);
    }

    @Test
    void toResponseListOfNothingIsAnEmptyList() {
        assertThat(mapper.toResponseList(List.of())).isEmpty();
        assertThat(mapper.converted).isEmpty();
    }

    @Test
    void toResponseListReturnsAMutableList() {
        List<Response> responses = mapper.toResponseList(List.of(new Entity("first")));

        assertThat(responses).isInstanceOf(ArrayList.class);
        responses.add(new Response("added"));
        assertThat(responses).hasSize(2);
    }

    @Test
    void toResponseListDoesNotDefendAgainstANullList() {
        assertThatThrownBy(() -> mapper.toResponseList(null))
                .isInstanceOf(NullPointerException.class);
    }
}
